// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: owner address, spender address, initialOwnerBalance, approveAmount, transferAmount
    function testFuzz_property(address ownerAddr, address spender, uint256 initialOwnerBalance, uint256 approveAmount, uint256 transferAmount) public {
        // keep addresses distinct and non-zero
        vm.assume(ownerAddr != address(0));
        vm.assume(spender != address(0));
        vm.assume(ownerAddr != spender);

        // bound balances/amounts to sane ranges within totalSupply
        uint256 maxSupply = c.totalSupply();
        initialOwnerBalance = bound(initialOwnerBalance, 0, maxSupply);
        approveAmount = bound(approveAmount, 0, maxSupply);
        transferAmount = bound(transferAmount, 0, maxSupply);

        // set up: give ownerAddr some tokens by having contract owner distribute to them
        // c was deployed by this test contract's msg.sender in setUp(), which is address(this)
        // But constructor set owner = msg.sender at deployment; owner is this test contract.
        // We need to make the contract's owner (this) have tokens already: on deploy balances[owner] = totalDistributed via NETM() which was only callable by owner. However reference C's constructor doesn't call NETM; but NETM() is public onlyOwner. In original C contract setUp new C() makes owner==address(this) and totalDistributed was preset; we will call NETM() to initialize balances of owner.
        // Call NETM() as contract owner (this) to set balances[this] = totalDistributed
        c.NETM();

        // transfer tokens from test owner to ownerAddr to set initialOwnerBalance
        uint256 ownerInitial = c.balanceOf(address(this));
        // bound initialOwnerBalance to what test owner actually has
        if (initialOwnerBalance > ownerInitial) initialOwnerBalance = ownerInitial;
        if (initialOwnerBalance > 0) {
            bool ok = c.transfer(ownerAddr, initialOwnerBalance);
            require(ok);
        }

        // impersonate ownerAddr to approve spender
        vm.startPrank(ownerAddr);
        // make sure ownerAddr has the token balance we intend
        // approve some amount
        bool apr = c.approve(spender, approveAmount);
        require(apr);
        vm.stopPrank();

        // record allowance before transfer
        uint256 beforeAllowance = c.allowance(ownerAddr, spender);

        // perform transferFrom as spender, transferring up to both balances and allowance
        // ensure transferAmount is not greater than owner's balance or allowance to guarantee success
        uint256 ownerBal = c.balanceOf(ownerAddr);
        uint256 allowedAmt = beforeAllowance;
        uint256 allowedMax = min(ownerBal, allowedAmt);
        // if allowedMax == 0 then transferFrom would revert; we still allow fuzz to cover both
        transferAmount = bound(transferAmount, 0, allowedMax);

        // perform the call and ignore revert (we only assert on allowance when call succeeds)
        bool callSucceeded;
        try c.transferFrom(ownerAddr, address(this), transferAmount) {
            callSucceeded = true;
        } catch {
            callSucceeded = false;
        }

        // single universal assertion: if transferFrom succeeded then allowance decreased by transferAmount
        // This is true for reference C for all inputs; mutant that doesn't subtract will fail when transferAmount>0
        if (callSucceeded) {
            uint256 afterAllowance = c.allowance(ownerAddr, spender);
            assertTrue(afterAllowance + transferAmount == beforeAllowance);
        } else {
            // if the call reverted, then allowance must be unchanged (transfer didn't happen)
            uint256 afterAllowance = c.allowance(ownerAddr, spender);
            assertTrue(afterAllowance == beforeAllowance);
        }
    }

    function min(uint256 a, uint256 b) internal pure returns (uint256) { return a <= b ? a : b; }
}
